export interface ReflexFiredPayload {
  /**
   * The reflex name, for example eat or hazard_escape.
   */
  name: string;
  /**
   * Permanent identity of one life, such as ag_kestrel_01.
   */
  life_id: string;
  body_generation: number;
  /**
   * World age when the reflex fired.
   */
  tick: number;
  /**
   * The values the reflex's check returned.
   */
  trigger: {
    [k: string]: string | number | boolean | null;
  };
  outcome: {
    result: "handled" | "failed" | "abandoned";
    detail?: string;
  };
}

export interface SnapshotRequest {
  /**
   * Permanent identity of one life, such as ag_kestrel_01.
   */
  life_id: string;
  /**
   * Why the Mind wants a snapshot, for the logs, for example wake or sleep.
   */
  reason: string;
}

export type SnapshotPlan = {
  goal: string;
  action: string;
  status: string;
} | null;

export type SnapshotStuck = {
  action: string;
  repeat_count: number;
} | null;

export interface Snapshot {
  snapshot_id: string;
  /**
   * Permanent identity of one life, such as ag_kestrel_01.
   */
  agent_id: string;
  shard: string;
  /**
   * The snapshot revision the attention controller compares plans against (spec 5.3.2).
   */
  revision: number;
  /**
   * The Body's generation (restart counter) the snapshot was built in. Optional so older Bodies and the mock stay valid.
   */
  body_generation?: number;
  world_time: SnapshotWorldTime;
  self: SnapshotSelf;
  surroundings: SnapshotSurroundings;
  /**
   * @maxItems 50
   */
  heard: {
    from: string;
    text: string;
    age_seconds: number;
  }[];
  /**
   * @maxItems 100
   *
   * Items: Event payloads are typed in later packets, so this object only fixes its type name and allows other properties.
   */
  events_since_last_thought: {
    type: string;
    [k: string]: unknown;
  }[];
  current_plan?: SnapshotPlan;
  stuck?: SnapshotStuck;
}

export interface SnapshotWorldTime {
  day: number;
  time_of_day: "dawn" | "day" | "dusk" | "night";
  ticks: number;
  weather: "clear" | "rain" | "thunder";
}

export interface SnapshotSelf {
  position: SelfPosition;
  health: number;
  hunger: number;
  armor: number;
  /**
   * Null when the hand is empty.
   */
  held_item: string | null;
  inventory: ItemStack[];
  effects: string[];
  budget_remaining_thoughts: number;
  days_since_sleep: number;
  /**
   * Item names the agent can craft because it has unlocked their recipes (spec 5.2, decision 0048). Optional: a Body without recipe knowledge omits it.
   *
   * @maxItems 1500
   *
   * Items: An item ID without its namespace prefix, such as iron_ingot.
   */
  unlocked_recipes?: string[];
}

export interface SnapshotSurroundings {
  blocks_summary: string;
  notable_blocks: {
    type: string;
    x: number;
    y: number;
    z: number;
    text?: string;
  }[];
  entities: {
    type: string;
    distance: number;
    direction: string;
  }[];
  agents: {
    name: string;
    distance: number;
    held_item: string | null;
    health_estimate: string;
  }[];
}

